1	package credit
2	
3	import (
4		"strings"
5		"testing"
6	)
7	
8	// 本文件为“提交修读结果时按用户给出的完整编号确定成绩归属”这项行为提供
9	// 回归保障。记录文件可以合法保存带前后空白的学生编号与修读编号（登记入口
10	// 会修剪编号，但既有文件中的编号原文不得改写，Load 也按原样接受），因此
11	// 全部用例直接构造记录文件，聚焦 pass/fail 的选对象逻辑：
12	//   - “s1”与“ s1 ”是两名不同学生，同一学生名下“e1”与“ e1 ”是两份
13	//     不同修读；普通空格、制表符、全角空格（U+3000）都是编号内容；
14	//   - 给带空白的编号提交结果只命中编号完全一致的那一份，另一名学生或
15	//     另一份修读的状态、学分与来源保持原样；
16	//   - 完整编号找不到学生时明确报学生不存在，学生存在但名下没有该完整
17	//     修读编号时明确报名下不存在该修读；即使去掉空白能碰上另一条记录，
18	//     也绝不借用那份记录或补建修读；
19	//   - 含前后空白的编号本身合法，绝不能判为文件损坏；
20	//   - 准确命中后沿用现有规则：重复提交相同结果幂等返回，改提另一结果拒绝。
21	
22	// whitespaceBase 构造一份结构完整、引用齐全的合法记录：
23	// 学生 "s1" 与 " s1 "（前后普通空格）各自的要求 r1 指向 4 学分课程 c1，
24	// 名下各有一份尚未提交结果的修读 e1。
25	func whitespaceBase() *fileData {
26		return &fileData{
27			Version: recordVersion,
28			Courses: []*Course{
29				{ID: "c1", Name: "高等数学", Credit: 4, Open: true},
30			},
31			Students: []*Student{{ID: "s1"}, {ID: " s1 "}},
32			Requirements: []*Requirement{
33				{ID: "r1", StudentID: "s1", CourseID: "c1"},
34				{ID: "r1", StudentID: " s1 ", CourseID: "c1"},
35			},
36			Enrollments: []*Enrollment{
37				{ID: "e1", StudentID: "s1", ReqID: "r1", Term: "2024春", Result: Enrolled},
38				{ID: "e1", StudentID: " s1 ", ReqID: "r1", Term: "2024春", Result: Enrolled},
39			},
40		}
41	}
42	
43	// mustLoadWhitespace 加载合法记录；含前后空白编号的记录必须被接受，
44	// 不能判为文件损坏。
45	func mustLoadWhitespace(t *testing.T, d *fileData) (*Store, string) {
46		t.Helper()
47		path, _ := writeRecord(t, d)
48		s, _, err := Load(path)
49		if err != nil {
50			t.Fatalf("含前后空白编号的记录是合法记录，不应判为损坏：%v", err)
51		}
52		return s, path
53	}
54	
55	// TestSubmitResultWhitespaceStudentIDsExact 两名学生 "s1" 与 " s1 " 各有
56	// 一份未提交结果的 e1：给 " s1 " 提交通过只命中本人的修读，核对按本人
57	// 要求获得学分并以本人的修读说明来源；"s1" 的状态、学分与来源保持原样。
58	func TestSubmitResultWhitespaceStudentIDsExact(t *testing.T) {
59		s, _ := mustLoadWhitespace(t, whitespaceBase())
60	
61		e, changed, err := s.SubmitResult(" s1 ", "e1", Passed)
62		if err != nil || !changed {
63			t.Fatalf("给 \" s1 \" 的 e1 提交通过应成功，changed=%v err=%v", changed, err)
64		}
65		if e.StudentID != " s1 " || e.ID != "e1" {
66			t.Fatalf("命中的应是 \" s1 \" 本人的 e1，得到 %+v", e)
67		}
68	
69		// " s1 " 本人：要求满足、4 学分、来源为本人修读 e1。
70		rep := s.CheckStudent(" s1 ")
71		if !rep.Found || rep.TotalCredits != 4 {
72			t.Fatalf("\" s1 \" 应凭本人 e1 获得 4 学分，得到 %+v", rep)
73		}
74		if len(rep.Requirements) != 1 || rep.Requirements[0].Source != "enrollment" ||
75			rep.Requirements[0].PassedEnrollmentID != "e1" {
76			t.Fatalf("\" s1 \" 的来源应是本人的通过修读 e1，得到 %+v", rep.Requirements)
77		}
78	
79		// "s1" 保持原样：e1 仍是选课、0 学分、要求未满足。
80		if got := s.Enrollment("s1", "e1"); got == nil || got.Result != Enrolled {
81			t.Fatalf("\"s1\" 的 e1 不应被改写，得到 %+v", got)
82		}
83		rep = s.CheckStudent("s1")
84		if !rep.Found || rep.TotalCredits != 0 || len(rep.Unmet) != 1 || rep.Unmet[0] != "r1" {
85			t.Fatalf("\"s1\" 应仍为 0 学分且 r1 未满足，得到 %+v", rep)
86		}
87	}
88	
89	// TestSubmitResultWhitespaceEnrollmentIDsExact 同一学生名下的 "e1" 与
90	// " e1 " 是两份独立修读：提交其中一份不改变另一份，既不误报重复提交，
91	// 也不误报结果冲突。
92	func TestSubmitResultWhitespaceEnrollmentIDsExact(t *testing.T) {
93		d := &fileData{
94			Version: recordVersion,
95			Courses: []*Course{
96				{ID: "c1", Name: "高等数学", Credit: 4, Open: true},
97			},
98			Students:     []*Student{{ID: "s1"}},
99			Requirements: []*Requirement{{ID: "r1", StudentID: "s1", CourseID: "c1"}},
100			Enrollments: []*Enrollment{
101				// "e1" 已提交通过，" e1 " 尚未提交结果：提交 " e1 " 时绝不能
102				// 因去空白撞上 "e1" 而误报重复提交或结果冲突。
103				{ID: "e1", StudentID: "s1", ReqID: "r1", Term: "2024春", Result: Passed, ResultSeq: 1},
104				{ID: " e1 ", StudentID: "s1", ReqID: "r1", Term: "2024秋", Result: Enrolled},
105			},
106			NextResultSeq: 1,
107		}
108		s, _ := mustLoadWhitespace(t, d)
109	
110		e, changed, err := s.SubmitResult("s1", " e1 ", Failed)
111		if err != nil || !changed {
112			t.Fatalf("给 \" e1 \" 提交未通过应作为独立修读被接受，changed=%v err=%v", changed, err)
113		}
114		if e.ID != " e1 " || e.Result != Failed || e.Term != "2024秋" {
115			t.Fatalf("命中的应是 \" e1 \" 本身且学期不变，得到 %+v", e)
116		}
117		// 未通过不得学分，但原有通过记录与学分保持原样。
118		if got := s.Enrollment("s1", "e1"); got == nil || got.Result != Passed {
119			t.Fatalf("原有 \"e1\" 的通过结果不应被改写，得到 %+v", got)
120		}
121		if rep := s.CheckStudent("s1"); rep.TotalCredits != 4 ||
122			rep.Requirements[0].PassedEnrollmentID != "e1" {
123			t.Fatalf("学分与来源应保持来自 \"e1\" 的通过，得到 %+v", rep)
124		}
125	
126		// 两份修读各自独立：对 " e1 " 重复提交未通过幂等返回；改提通过拒绝。
127		if _, changed, err := s.SubmitResult("s1", " e1 ", Failed); err != nil || changed {
128			t.Fatalf("对 \" e1 \" 重复提交未通过应幂等返回，changed=%v err=%v", changed, err)
129		}
130		if _, _, err := s.SubmitResult("s1", " e1 ", Passed); err == nil {
131			t.Fatal("\" e1 \" 已提交未通过后改提通过应被拒绝")
132		}
133		if got := s.Enrollment("s1", " e1 "); got.Result != Failed {
134			t.Fatalf("拒绝后 \" e1 \" 应保留未通过，得到 %+v", got)
135		}
136	}
137	
138	// TestSubmitResultWhitespaceNoBorrow 完整编号找不到时必须明确拒绝：
139	// 即使去掉空白后能碰上另一名学生或另一份修读，也绝不借用那份记录，
140	// 更不能补建修读。普通空格、制表符、全角空格一样不能被忽略。
141	func TestSubmitResultWhitespaceNoBorrow(t *testing.T) {
142		d := &fileData{
143			Version: recordVersion,
144			Courses: []*Course{
145				{ID: "c1", Name: "高等数学", Credit: 4, Open: true},
146			},
147			Students:     []*Student{{ID: "s1"}},
148			Requirements: []*Requirement{{ID: "r1", StudentID: "s1", CourseID: "c1"}},
149			Enrollments: []*Enrollment{
150				{ID: "e1", StudentID: "s1", ReqID: "r1", Term: "2024春", Result: Enrolled},
151			},
152		}
153	
154		// 学生编号带各种前后空白：文件中只有 "s1"，这些都应报学生不存在。
155		for _, student := range []string{" s1", "s1 ", " s1 ", "\ts1\t", "　s1　"} {
156			s, _ := mustLoadWhitespace(t, d)
157			_, _, err := s.SubmitResult(student, "e1", Passed)
158			if err == nil || !strings.Contains(err.Error(), "不存在") {
159				t.Fatalf("学生 %q 不存在，提交应明确拒绝，得到 %v", student, err)
160			}
161			if !strings.Contains(err.Error(), "学生") {
162				t.Fatalf("学生 %q 找不到时应明确报告学生不存在，得到 %v", student, err)
163			}
164			// 不能借用 "s1" 的修读，也不能补建记录。
165			if got := s.Enrollment("s1", "e1"); got == nil || got.Result != Enrolled {
166				t.Fatalf("学生 %q 被拒绝后 \"s1\" 的 e1 不应变化，得到 %+v", student, got)
167			}
168			if got := s.Enrollment(student, "e1"); got != nil {
169				t.Fatalf("不应为学生 %q 补建修读，得到 %+v", student, got)
170			}
171			if s.Dirty() {
172				t.Fatalf("被拒绝的提交不应产生变更（学生 %q）", student)
173			}
174		}
175	
176		// 学生存在但修读编号带各种前后空白：应报该学生名下不存在该修读。
177		for _, enrID := range []string{" e1", "e1 ", " e1 ", "\te1\t", "　e1　"} {
178			s, _ := mustLoadWhitespace(t, d)
179			_, _, err := s.SubmitResult("s1", enrID, Passed)
180			if err == nil || !strings.Contains(err.Error(), "不存在") {
181				t.Fatalf("修读 %q 不存在于 s1 名下，提交应明确拒绝，得到 %v", enrID, err)
182			}
183			if !strings.Contains(err.Error(), "s1") {
184				t.Fatalf("错误应点名学生 s1 名下不存在该修读，得到 %v", err)
185			}
186			if got := s.Enrollment("s1", "e1"); got == nil || got.Result != Enrolled {
187				t.Fatalf("修读 %q 被拒绝后 \"e1\" 不应变化，得到 %+v", enrID, got)
188			}
189			if got := s.Enrollment("s1", enrID); got != nil {
190				t.Fatalf("不应补建修读 %q，得到 %+v", enrID, got)
191			}
192			if s.Dirty() {
193				t.Fatalf("被拒绝的提交不应产生变更（修读 %q）", enrID)
194			}
195		}
196	}
197	
198	// TestSubmitResultWhitespaceIdempotentAndConflictRules 准确命中带空白的
199	// 修读后沿用现有规则：重复提交相同结果返回原记录且不产生变更；已提交
200	// 结果改提另一结果拒绝并保留原结果。
201	func TestSubmitResultWhitespaceIdempotentAndConflictRules(t *testing.T) {
202		s, _ := mustLoadWhitespace(t, whitespaceBase())
203	
204		if _, changed, err := s.SubmitResult(" s1 ", "e1", Passed); err != nil || !changed {
205			t.Fatalf("首次提交通过应成功，changed=%v err=%v", changed, err)
206		}
207		s.dirty = false // 只看后续提交是否产生新变更
208	
209		// 重复提交相同结果：幂等返回原记录，不再产生变更。
210		e, changed, err := s.SubmitResult(" s1 ", "e1", Passed)
211		if err != nil || changed {
212			t.Fatalf("重复提交相同结果应幂等返回，changed=%v err=%v", changed, err)
213		}
214		if e.StudentID != " s1 " || e.Result != Passed {
215			t.Fatalf("幂等返回的应是原记录，得到 %+v", e)
216		}
217		if s.Dirty() {
218			t.Fatal("幂等重复提交不应产生变更")
219		}
220	
221		// 改提另一结果：拒绝并保留通过。
222		if _, _, err := s.SubmitResult(" s1 ", "e1", Failed); err == nil {
223			t.Fatal("已提交通过后改提未通过应被拒绝")
224		}
225		if got := s.Enrollment(" s1 ", "e1"); got.Result != Passed {
226			t.Fatalf("拒绝后应保留通过结果，得到 %+v", got)
227		}
228		if s.Dirty() {
229			t.Fatal("被拒绝的改提不应产生变更")
230		}
231	}
